using BC.FixedAsset.Services;using System;using System.Web.UI.WebControls;namespace BC.FixedAsset.Web.FixedAsset.Review{public partial class FinanceReview:SecurePage{protected GridView gridReview;protected TextBox txtReason;protected Label lblMessage;private readonly AssetSurveyService service=new AssetSurveyService();protected void Page_Load(object s,EventArgs e){if(!IsPostBack)Bind();}private void Bind(){gridReview.DataSource=service.Search("","FinanceReview",AssetAccess,"FinanceReview");gridReview.DataBind();}protected void Grid_RowCommand(object s,GridViewCommandEventArgs e){try{var id=Convert.ToInt64(e.CommandArgument);if(e.CommandName=="ApproveSurvey")service.Approve(id,AssetAccess);if(e.CommandName=="ReturnSurvey")service.Return(id,txtReason.Text,AssetAccess);txtReason.Text="";Bind();lblMessage.Text="ดำเนินการเรียบร้อย";}catch(Exception ex){lblMessage.Text=Server.HtmlEncode(ex.Message);}}}}
